						try { await loadCandles(); await refreshDeltaZero(); await refreshMonthlyDeltaZero(); await refreshAllDeltaZero(); await refreshTomorrowDeltaZero(); await refreshDayAfterTomorrowDeltaZero(); await refreshBands(); await refreshLiveBandDots(); await refreshZonesBoxes(); await refreshNearestExpiry(); await refreshLastTrade(); await refreshGammaTops(); await refreshStrikeGamma(); await updateForecastVisibility(); }
						catch (e) { setStatus('Error: ' + e.message); }
					}
					init();
